using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class CombReferenceIntegration {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Art="Assets/UnderwaterArt/CombReferenceMotion/",Output="Renders/CombReferenceMotion/";
 static Vector3[] Points(SkinnedMeshRenderer s)=>OctopusRepairValidation.Points(s);
 static Bounds Box(Vector3[] points){var b=new Bounds(points[0],Vector3.zero);foreach(var p in points)b.Encapsulate(p);return b;}
 static SeaLife[] Actors()=>UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(a=>a.kind=="Comb jelly").ToArray();
 public static void Apply(){
  AssetDatabase.Refresh();Directory.CreateDirectory(Output);var importer=(ModelImporter)AssetImporter.GetAtPath(Art+"CombReference.fbx");importer.animationType=ModelImporterAnimationType.Legacy;importer.importAnimation=true;importer.isReadable=true;importer.animationCompression=ModelImporterAnimationCompression.Off;importer.materialImportMode=ModelImporterMaterialImportMode.None;var clips=importer.defaultClipAnimations;foreach(var clip in clips){clip.name="CombLobeWave";clip.loopTime=true;clip.wrapMode=WrapMode.Loop;}importer.clipAnimations=clips;importer.SaveAndReimport();
  var scene=EditorSceneManager.OpenScene(Scene);var asset=AssetDatabase.LoadAssetAtPath<GameObject>(Art+"CombReference.fbx");var material=AssetDatabase.LoadAssetAtPath<Material>(Art+"Tissue.mat");if(!material){material=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/UnderwaterArt/CombJellyComparison/Tissue.mat"));AssetDatabase.CreateAsset(material,Art+"Tissue.mat");}material.SetFloat("_UseCombCoordinates",1);EditorUtility.SetDirty(material);Mesh shared=null;
  foreach(var actor in Actors()){
   var old=actor.transform.Find("Prepared animated model");if(!old)throw new Exception("No original comb visual");var wrapper=new GameObject("Reference comb visual").transform;wrapper.SetParent(actor.transform,false);wrapper.localPosition=old.localPosition;wrapper.localRotation=old.localRotation;wrapper.localScale=old.localScale;var model=(GameObject)PrefabUtility.InstantiatePrefab(asset);model.transform.SetParent(wrapper,false);PrefabUtility.UnpackPrefabInstance(model,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var player=model.GetComponent<Animation>();player.enabled=false;player.playAutomatically=false;player.clip.SampleAnimation(model,0);var skin=model.GetComponentInChildren<SkinnedMeshRenderer>();skin.sharedMaterial=material;skin.allowOcclusionWhenDynamic=false;skin.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
   if(!shared){shared=UnityEngine.Object.Instantiate(skin.sharedMesh);shared.name="Comb jelly reference lobe anatomy";var p=Points(skin).Select(actor.transform.InverseTransformPoint).ToArray();var b=Box(p);shared.uv3=p.Select(v=>new Vector2(Mathf.InverseLerp(b.min.y,b.max.y,v.y),0)).ToArray();var path=Art+"AnatomicalRows.asset";var previous=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(previous){EditorUtility.CopySerialized(shared,previous);UnityEngine.Object.DestroyImmediate(shared);shared=previous;EditorUtility.SetDirty(shared);}else AssetDatabase.CreateAsset(shared,path);}skin.sharedMesh=shared;
   Bounds envelope=default,visible=default;for(int frame=0;frame<=72;frame++){player.clip.SampleAnimation(model,player.clip.length*frame/72);var points=Points(skin);var a=Box(points.Select(actor.transform.InverseTransformPoint).ToArray());var b=Box(points.Select(skin.rootBone.InverseTransformPoint).ToArray());if(frame==0){envelope=a;visible=b;}else{envelope.Encapsulate(a);visible.Encapsulate(b);}}var scale=skin.rootBone.lossyScale;visible.Expand(.06f/Mathf.Max(.0001f,Mathf.Abs(scale.x)));skin.localBounds=visible;player.clip.SampleAnimation(model,0);
   UnityEngine.Object.DestroyImmediate(old.gameObject);wrapper.name="Prepared animated model";// Comb tissue uses normal camera/frustum visibility, without a hard distance cutoff.
   var motion=actor.GetComponent<JellyReferenceMotion>();motion.player=player;motion.comb=true;EditorUtility.SetDirty(motion);var guard=actor.GetComponent<ReefAnimalClearance>();envelope.Expand(.02f);guard.animatedBody=envelope;EditorUtility.SetDirty(guard);
   var info=actor.GetComponent<ReefCreatureInfo>();info.localFocus=Box(Points(skin).Select(actor.transform.InverseTransformPoint).ToArray()).center;EditorUtility.SetDirty(info);VRFeedbackRepair.FitJelly(actor);var zone=actor.GetComponent<ReefDangerZone>();zone.cautionDistance=.025f;zone.proximityDistance=.06f;foreach(var c in zone.surfaces.OfType<BoxCollider>())c.size*=.92f;EditorUtility.SetDirty(zone);
  }
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("COMB_REFERENCE_APPLIED count="+Actors().Length);Validate();
 }
 public static void Validate(){
  EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);int checks=0;float maximum=0,bodyGirthRange=0;foreach(var actor in Actors()){
   var rootPose=actor.transform.localToWorldMatrix;var motion=actor.GetComponent<JellyReferenceMotion>();var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();if(skin.bones.Length<10||!skin.bones.Any(b=>b.name=="LobeLeftTip")||skin.sharedMesh.triangles.Length/3!=21999||!motion.player||motion.player.enabled)throw new Exception("Reference comb rig missing");var player=motion.player;player.clip.SampleAnimation(player.gameObject,0);var first=Points(skin);player.clip.SampleAnimation(player.gameObject,player.clip.length);var last=Points(skin);if(first.Zip(last,(a,b)=>Vector3.Distance(a,b)).Max()>.0005f)throw new Exception("Comb loop seam");
   var weights=skin.sharedMesh.boneWeights;var bodyIndices=Enumerable.Range(0,weights.Length).Where(i=>skin.bones[weights[i].boneIndex0].name=="BodyCrown"||skin.bones[weights[i].boneIndex0].name=="BodyWaist").ToArray();if(bodyIndices.Length<100)throw new Exception("Main body has no deformation weights");float narrow=float.MaxValue,wide=0;
   for(int i=0;i<97;i++){motion.Step(.05f);var points=Points(skin);var body=Box(bodyIndices.Select(index=>actor.transform.InverseTransformPoint(points[index])).ToArray());float girth=Mathf.Max(body.size.x,body.size.z);narrow=Mathf.Min(narrow,girth);wide=Mathf.Max(wide,girth);var bounds=skin.bounds;bounds.Expand(.015f);var ground=actor.GetComponent<ReefAnimalClearance>().animatedBody;ground.Expand(.001f);foreach(var p in points){if(!bounds.Contains(p)||!ground.Contains(actor.transform.InverseTransformPoint(p)))throw new Exception("Comb animation escaped bounds");}maximum=Mathf.Max(maximum,first.Zip(points,(a,b)=>Vector3.Distance(a,b)).Max());checks++;}if(wide-narrow<.025f)throw new Exception("Main body is not visibly deforming");bodyGirthRange=Mathf.Max(bodyGirthRange,wide-narrow);if(rootPose!=actor.transform.localToWorldMatrix)throw new Exception("Animation moved the gameplay root");if(actor.danger||actor.consequence)throw new Exception("Comb safety changed");var zone=actor.GetComponent<ReefDangerZone>();if(zone.surfaces.Length<5||zone.surfaces.Any(c=>!c||!c.isTrigger))throw new Exception("Comb contact rig missing");if(actor.GetComponentsInChildren<LODGroup>().Length>0)throw new Exception("Comb still has distance cutoff");
  }if(maximum<.035f)throw new Exception("Body wave too small "+maximum);if(ShaderUtil.ShaderHasError(Shader.Find("Underwater/Reference Comb Tissue")))throw new Exception("Comb shader compilation");File.WriteAllText(Output+"Validation.txt","Comb jellies: "+Actors().Length+"\nRig: 11 joints with crown/waist body deformation; mesh: 21,999 triangles; loop: 4.8 seconds\nSampled poses: "+checks+"\nMaximum tissue displacement: "+maximum+" m\nMain-body width variation: "+bodyGirthRange+" m\nLoop seam, render/clearance bounds, root placement and fitted contact sensors passed. No comb distance-cull group.\n");ReefCollisionValidation.Run();Capture();Debug.Log("COMB_REFERENCE_VALIDATED");
 }
 public static void Capture(){
  EditorSceneManager.OpenScene(Scene);var actor=Actors().First();var motion=actor.GetComponent<JellyReferenceMotion>();motion.phase=0;var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();var bounds=Box(Points(skin));foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None))if(r!=skin)r.enabled=false;var camera=Camera.main;if(camera.TryGetComponent<ReefOptics>(out var optics))optics.enabled=false;camera.fieldOfView=45;camera.nearClipPlane=.02f;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.005f,.012f,.018f);RenderSettings.fog=false;camera.transform.position=bounds.center+actor.transform.right*bounds.size.magnitude*1.6f+actor.transform.forward*bounds.size.magnitude*.15f;camera.transform.LookAt(bounds.center);
  for(int frame=0;frame<48;frame++){motion.Step(frame==0?0:.1f);ReefCorrectionAudit.Capture(camera,Output+"Frame_"+frame.ToString("D3")+".png");}
 }
 public static void ReviewAngles(){
  EditorSceneManager.OpenScene(Scene);var actor=Actors().First();var motion=actor.GetComponent<JellyReferenceMotion>();motion.phase=0;motion.Step(2.4f);var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();var b=Box(Points(skin));foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None))if(r!=skin)r.enabled=false;var camera=Camera.main;if(camera.TryGetComponent<ReefOptics>(out var optics))optics.enabled=false;camera.fieldOfView=45;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.005f,.012f,.018f);RenderSettings.fog=false;foreach(int angle in new[]{45,90,180}){camera.transform.position=b.center+Quaternion.AngleAxis(angle,actor.transform.up)*actor.transform.right*b.size.magnitude*1.6f;camera.transform.LookAt(b.center);ReefCorrectionAudit.Capture(camera,Output+"View_"+angle+".png");}Debug.Log("COMB_REFERENCE_ANGLES_CAPTURED");
 }
}
}
